def ic(n): return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="'+D[n]+'"/></svg>'
for n in D: (S/('icon-'+n.lower()+'.svg')).write_text(ic(n),encoding='utf-8')
def bt(n,a=False,t=''): return '<button title="'+n+'" class="'+('active' if a else '')+'">'+ic(n)+t+'</button>'
def th(n,actor=False): return '<i class="thumb '+('actor' if actor else '')+'" style="background-image:url(assets/'+n+'.png)"></i>'
def fld(n,v):return '<div class="field"><label>'+n+'</label><span>'+v+'</span></div>'
def grp(n):return '<div class="group">'+n+'</div>'
def insp(k='Prop'):
 pic={'Prop':'crate1','Light':'fantasytorch1','NPC':'goblin1'}[k]
 fields={'Prop':[('Type','crate1 ▾'),('Rotation','90°'),('Height','0.00'),('Scale','1.00'),('Texture','crate1 ▾'),('Stack on top','☐')],'Light':[('Type','Point ▾'),('Hue','🟨 38°'),('Intensity','1.20'),('Range','3.00'),('Height','1.60'),('Bulb visible','☑'),('Effect','Flicker ▾')],'NPC':[('Type','goblin1 ▾'),('Direction','N / E / S / W'),('Path','3 points · Clear')]}[k]
 s='<div class="panel inspector"><header>'+ic('NPC' if k=='NPC' else 'Light' if k=='Light' else 'Textured')+k+' <small>Inspector</small><b>›</b></header><div class="identity">'+th(pic,k=='NPC')+'<div><strong>'+pic+'</strong><small>Cell 8, 6 · #12</small></div></div>'+grp('▾ Transform' if k=='Prop' else '▾ Settings')+''.join(fld(n,v) for n,v in fields)
 if k=='NPC': s+=grp('▾ Advanced · until alert')+''.join(fld(n,v) for n,v in [('Mode','dormant ▾'),('Alternatives','fooled / arrive'),('Frequency','2'),('Max','3')])
 s+=grp('▾ Logic')+fld('Chance','100 %')+fld('with','—')+fld('without','—')
 if k!='NPC':s+=grp('▸ Advanced')
 return s+'<footer>Duplicate <span>Delete</span></footer></div>'
