def tree():
 s='<div class="panel tree"><header>Assets <b>‹</b></header><div class="search">'+ic('Search')+' Search name or kind…</div><div class="filters">Void Fantasy ▾ <small>☐ Active category only</small></div><div class="treehead">Map Settings</div>'
