 for cat,c,ns in cats:
  s+='<div class="treehead" style="border-left-color:'+c+'">▾ '+cat+'<span>'+ic('Eye')+'</span></div>'
  if cat=='Textures': s+='<small class="tabs">Wall · Floor · Ceiling · Default</small>'
