 for n,c in [('Lights',COL['Light']),('Particles',COL['Particle']),('Doors',COL['Door']),('Markers',COL['Start'])]:s+='<div class="treehead" style="border-left-color:'+c+'">▸ '+n+'<span>'+ic('Eye')+'</span></div>'
