def viewport(n,build=False,sel=False,tr=False,compact=False,variant='a',mobile=False,portrait=False):
 cls=('build ' if build else '')+('compact ' if compact else '')+('toolbar-only ' if n.startswith('toolbar') else '')+('strip ' if variant!='a' else '')+('mobile ' if mobile else '')+('portrait ' if portrait else '')
 b='<div class="scene"><div class="backdrop"><img src="assets/2-editor-prop-tool.jpg"></div><div class="shade"></div></div>'+tools()+mini(build)+(tree() if tr else '' if build else '<div class="rail glass">'+bt('Layers')+bt('Search')+'</div>')+insp('Light' if sel else 'Prop')+selection(sel)+status(build,sel)
 if variant=='c':b+='<div class="radial">'+bt('Door')+bt('Ladder')+bt('Bridge')+bt('Start')+'<small>Quick</small></div>'
 if sel:b+='<div class="selecthint">ALT held · Global Select · release to return to Paint</div><div class="note">Paint → <b>Select</b><br>Inspector: Light #4<br>Alt felengedése: Paint visszatér.<br>A kijelölés megmarad.</div>'
 if mobile:b=b.replace('Decorate <em>/ Build</em>','').replace('Drag: move · Ctrl+drag: duplicate · R: 90° · Shift+R: 15° · PgUp/PgDn: height · F: focus','Select · Long-press: grab · Duplicate · Rotate')
 save(n,b,cls)
